528		\[
529			\bigl\| (\Id - Q_{\mathrm{A}}) \ket{\Delta} \bigr\|^2
530			= \bigl\| (\Id - Q_{\mathrm{A}}) (\ket{\Delta} - \ket{\vartheta}) \bigr\|^2
